    ('Quelle est l’inverse de [[2,1],[1,1]] ?', '[[1,−1],[−1,2]]', (M([[2, 1], [1, 1]]).inv(), M([[1, -1], [-1, 2]]))),
    ('Quelle aire engendrent les vecteurs (2,0) et (1,3) ?', '6', (abs(M([[2, 1], [0, 3]]).det()), S.Integer(6))),
