    ('Q=(1/√2)[[1,1],[1,−1]]. Que vaut QᴴQ ?', 'I₂', ((M([[1, 1], [1, -1]]) / S.sqrt(2)).H * (M([[1, 1], [1, -1]]) / S.sqrt(2)), S.eye(2))),
