    ('Pour J=[[2,1],[0,2]], quelle est la dimension de l’espace propre associé à 2 ?', '1', (S.Integer(len((M([[2, 1], [0, 2]]) - 2 * S.eye(2)).nullspace())), S.Integer(1))),
    ('Quelles sont les valeurs singulières de diag(3,−2) ?', '3 et 2', (V(sorted([S.sqrt(v) for v in (S.diag(3, -2).T * S.diag(3, -2)).eigenvals()])), V([2, 3]))),
