course=json.load(open('curriculum/courses/mit_18_06sc_2011.json',encoding='utf-8'))
answers={e['prompt']:e['options'][e['correctOptionIndex']] for l in course['lessons'] for e in l['exercises']}
for prompt,expected,(left,right) in cases:
    delta=left-right
    assert (all(S.simplify(x)==0 for x in delta) if isinstance(delta,S.MatrixBase) else S.simplify(delta)==0),prompt
    assert answers[prompt]==expected,(prompt,answers[prompt],expected)
print('PASS',len(cases),'exact calculations tied to current selected answers')
